#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Event {
    int x, y1, y2, delta;
    bool operator<(const Event& other) const {
        return x < other.x;
    }
};

struct SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len;
    vector<ll> ys;

    SegmentTree(int _n, const vector<ll>& _ys): n(_n), ys(_ys) {
        cnt.assign(4*n, 0);
        len.assign(4*n, 0);
    }

    void pull(int node, int l, int r) {
        if (cnt[node] > 0) {
            len[node] = ys[r+1] - ys[l];
        } else if (l == r) {
            len[node] = 0;
        } else {
            len[node] = len[node<<1] + len[node<<1|1];
        }
    }

    void update(int node, int l, int r, int ql, int qr, int delta) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            cnt[node] += delta;
            pull(node, l, r);
            return;
        }
        int mid = (l + r) >> 1;
        update(node<<1,   l,     mid, ql, qr, delta);
        update(node<<1|1, mid+1, r,   ql, qr, delta);
        pull(node, l, r);
    }
    void modify(int y1i, int y2i, int delta) {
        update(1, 0, n-1, y1i, y2i-1, delta);
    }
    ll covered_length() const {
        return len[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<Event> events;
    events.reserve(2*N);
    vector<ll> ys;
    ys.reserve(2*N);

    for (int i = 0; i < N; i++) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        events.push_back({int(x1), int(y1), int(y2), +1});
        events.push_back({int(x2), int(y1), int(y2), -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    int M = (int)ys.size() - 1;
    auto get_yi = [&](ll y) {
        return int(lower_bound(ys.begin(), ys.end(), y) - ys.begin());
    };
    for (auto& e : events) {
        e.y1 = get_yi(e.y1);
        e.y2 = get_yi(e.y2);
    }

    sort(events.begin(), events.end());
    SegmentTree st((int)ys.size()-1, ys);

    ll ans = 0;
    int prev_x = events[0].x;
    for (auto& e : events) {
        int x = e.x;
        ll dx = ll(x) - ll(prev_x);
        if (dx > 0) {
            ans += dx * st.covered_length();
            prev_x = x;
        }
        st.modify(e.y1, e.y2, e.delta);
    }

    cout << ans << "\n";
}
